        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(I):
    I=np.array(I); H,W=I.shape
    vals,cnt=np.unique(I,return_counts=True); bg=int(vals[cnt.argmax()])
    fgrows=[r for r in range(H) if (I[r]!=bg).any()]
    bands=[]; cur=[fgrows[0]]
    for r in fgrows[1:]:
        if r==cur[-1]+1: cur.append(r)
        else: bands.append(cur); cur=[r]
    bands.append(cur)
    O=I.copy()
    def mcol(R): return int(max(c for c in range(W) if I[R,c]!=bg))
    # rule: per adjacent band pair, align by index; extend each shorter row's trailing bg with fg positions of its twin
    for i in range(len(bands)-1):
        b1,b2=bands[i],bands[i+1]
        for k in range(min(len(b1),len(b2))):
            r,r2=b1[k],b2[k]
            e=mcol(r); e2=mcol(r2)
