import os,re,numpy as np,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(I):
    I=np.array(I); H,W=I.shape
    vals,cnt=np.unique(I,return_counts=True); bg=int(vals[cnt.argmax()])
    fgrows=[r for r in range(H) if (I[r]!=bg).any()]
    bands=[]; cur=[fgrows[0]]
    for r in fgrows[1:]:
        if r==cur[-1]+1: cur.append(r)
        else: bands.append(cur); cur=[r]
    bands.append(cur)
    O=I.copy()
    def mcol(R): return int(max(c for c in range(W) if I[R,c]!=bg))
    # ref mode: every band except the fullest extends using index-aligned twin in fullest band
    def bsg(bb): return sum(mcol(R) for R in bb)
    ref=max(bands,key=bsg)
    for b in bands:
        if b is ref: continue
        n=min(len(b),len(ref))
        for k in range(n):
            r,rr=b[k],ref[k]
            if mcol(r)>mcol(rr): continue
            for c in range(mcol(r)+1,mcol(rr)+1):
                if I[r,c]==bg and I[rr,c]!=bg: O[r,c]=1
    return O.tolist()
for n in [5,6,7,8]:
    o=solve(G[f'Demo pair {n} input']); exp=G[f'Demo pair {n} output']
    print(n, bool(np.array_equal(np.array(o),np.array(exp))), np.argwhere(np.array(o)!=np.array(exp)).tolist()[:6])
